def _is_safe_artifact_url(url: str) -> bool:
    """Return whether a presigned artifact URL is safe to download from.

    Only ``http``/``https`` URLs whose host resolves exclusively to globally
    routable IP addresses are considered safe. Private, loopback, link-local,
    reserved, and otherwise non-public destinations are rejected to guard
    against SSRF when following server-supplied URLs. Non-http(s) schemes and
    malformed URLs are rejected as well.
    """
    try:
        parsed = urlparse(url)
    except ValueError:
        return False

    if parsed.scheme not in _ARTIFACT_URL_SCHEMES:
        return False

    try:
        hostname = parsed.hostname
    except ValueError:
        return False
    if not hostname:
        return False

    candidates: list[str] = []
    try:
        ipaddress.ip_address(hostname)
    except ValueError:
        # Not an IP literal: resolve the hostname and require every resolved
        # address to be globally routable.
        try:
            infos = socket.getaddrinfo(hostname, None)
        except (socket.gaierror, UnicodeError, OSError):
